// The trap behind every function the port has no source for yet (dread_port.h). The thunks that
// jump here are generated by tools/port_link.py from the whole-program link's undefined symbols, one
// per missing function, each loading that function's original address as the argument.

#include "dread_port.h"

#include <cstdio>
#include <cstdlib>

extern "C" void dread_port_missing_function(u64 address) {
    std::fprintf(stderr, "dread: call to a function with no source yet: fn_%llx (see data/functions/)\n",
                 static_cast<unsigned long long>(address));
    std::fflush(stderr);
    std::abort();
}
